// Generated by scripts/sync-core.mjs from mobile/src/chain/request.ts; edit it there and run npm run sync-core.
// Payment codes: what a Receive screen shows as a QR code and a Send screen
// accepts from a scan.
//
//   ting:<account>[?coin=<coin>]
//
// `account` and `coin` are 64 lowercase hex digits (the 32-byte account and
// coin contract id). The scheme is matched without regard to case, a `//`
// after it is tolerated, and parameters other than `coin` are ignored. A bare
// 64-digit account is accepted too, so a plain copied account also scans.
import { isHex } from './bytes';

export interface PaymentRequest {
  /** The receiving account, 64 lowercase hex digits. */
  account: string;
  /** The coin the receiver asks for, if the code names one. */
  coin?: string;
}

export const SCHEME = 'ting:';

/** Whether a text is written as a payment code (rather than, say, a bare account). */
export function isPaymentCode(text: string): boolean {
  return text.trim().toLowerCase().startsWith(SCHEME);
}

export function encodeRequest(request: PaymentRequest): string {
  const account = request.account.toLowerCase();
  if (!isHex(account, 32)) throw new Error('a payment code needs a 32-byte account');
  if (request.coin === undefined) return `${SCHEME}${account}`;
  const coin = request.coin.toLowerCase();
  if (!isHex(coin, 32)) throw new Error('a payment code needs a 32-byte coin ID');
  return `${SCHEME}${account}?coin=${coin}`;
}

/** The request a scanned or pasted text holds, or null when it is not a payment code. */
export function parseRequest(text: string): PaymentRequest | null {
  let rest = text.trim();
  if (isPaymentCode(rest)) {
    rest = rest.slice(SCHEME.length);
    if (rest.startsWith('//')) rest = rest.slice(2);
  } else if (rest.includes(':')) {
    return null;
  }
  const query = rest.indexOf('?');
  const account = (query < 0 ? rest : rest.slice(0, query)).replace(/\/$/, '');
  if (!isHex(account, 32)) return null;
  const out: PaymentRequest = { account: account.toLowerCase() };
  if (query < 0) return out;
  for (const part of rest.slice(query + 1).split('&')) {
    const eq = part.indexOf('=');
    const key = eq < 0 ? part : part.slice(0, eq);
    if (key.toLowerCase() !== 'coin') continue;
    const value = eq < 0 ? '' : part.slice(eq + 1);
    if (!isHex(value, 32)) return null;
    out.coin = value.toLowerCase();
  }
  return out;
}
